from PIL import Image
for tag,f in (("LIGHT","capture-r084-light.png"),("DARK","capture-r084-dark.png")):
    im=Image.open(f).convert("RGB"); W,H=im.size; px=im.load()
    print(f"== {tag} {W}x{H} ==")
    # field colour in an empty grid cell (Mon col, no chips), and weekend col
    print("  field Mon x300 y500:",px[300,500],"  Sun x1000 y500:",px[1000,500],"  gutter x25 y500:",px[25,500])
    # --- pill bbox: reddish pixels in x 0..70, y 280..345
    xs=[];ys=[]
    for y in range(275,350):
        for x in range(0,70):
            r,g,b=px[x,y]
            if r-g>60 and r-b>55: xs.append(x);ys.append(y)
    if xs: print(f"  PILL bbox x{min(xs)}..{max(xs)} y{min(ys)}..{max(ys)}  ({max(xs)-min(xs)+1}x{max(ys)-min(ys)+1})  centre=({(min(xs)+max(xs))/2},{(min(ys)+max(ys))/2})")
    else: print("  PILL: none")
    if xs:
        cy=(min(ys)+max(ys))//2
        print("    pill fill @x8:",px[8,cy]," mid @x25:",px[25,cy])
    # --- dot: reddish pixels x 700..820
    xs2=[];ys2=[]
    for y in range(290,330):
        for x in range(700,830):
            r,g,b=px[x,y]
            if r-g>60 and r-b>55: xs2.append(x);ys2.append(y)
    if xs2: print(f"  DOT bbox x{min(xs2)}..{max(xs2)} y{min(ys2)}..{max(ys2)}  centre=({(min(xs2)+max(xs2))/2},{(min(ys2)+max(ys2))/2})")
    else: print("  DOT: none")
    # --- LINE: per-column vertical scan of rows differing from the field, in x=100,300,450,600,700,870,1000
    print("  LINE rows (dev>6 from the field at that column):")
    for x in (100,300,450,600,700,870,1000,1090):
        field=px[x,500]
        rows=[y for y in range(285,330) if max(abs(c-d) for c,d in zip(px[x,y],field))>6]
        if not rows: print(f"    x={x:4d} field{field} -> NONE"); continue
        # group into runs
        runs=[];s=rows[0];p=rows[0]
        for y in rows[1:]:
            if y==p+1: p=y
            else: runs.append((s,p)); s=y; p=y
        runs.append((s,p))
        det=" ".join(f"y{a}-{b}{px[x,(a+b)//2]}" for a,b in runs)
        print(f"    x={x:4d} field{field} -> {det}")
